    public static function iconSvgs(): array
    {
        return collect(self::ICONS)
            ->map(fn (array $icon, string $slug): string => self::markup($slug, '{class}'))
            ->all();
    }

    public static function hosts(): array
    {
        return self::HOSTS;
    }

    public static function markup(string $slug, string $class = ''): string
    {
        $icon = self::ICONS[$slug] ?? self::ICONS['link'];

        return '<svg class="'.$class.'" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false">'
            .$icon['paths']
            .'</svg>';
    }

    public static function label(string $slug): string
    {
        return self::ICONS[$slug]['label'] ?? ucfirst(str_replace('-', ' ', $slug));
    }

    public static function resolve(string $url, ?string $manualIcon = null): array
    {
        if ($manualIcon !== null && $manualIcon !== '' && ! in_array($manualIcon, ['link', 'globe'], true) && isset(self::ICONS[$manualIcon])) {
            return self::data($manualIcon);
        }

        $url = trim($url);
        $lower = strtolower($url);

        foreach (['mailto:' => 'mail', 'tel:' => 'phone', 'sms:' => 'phone', 'whatsapp:' => 'whatsapp'] as $prefix => $slug) {
            if (str_starts_with($lower, $prefix)) {
                return self::data($slug);
            }
        }

        $host = null;
        $parsed = parse_url($url);

        if (is_array($parsed) && isset($parsed['host'])) {
            $host = preg_replace('/^www\./', '', strtolower($parsed['host']));
        }

        if ($host !== null && $host !== '') {
            foreach (self::HOSTS as $domain => $slug) {
                if ($host === $domain || str_ends_with($host, '.'.$domain)) {
                    return self::data($slug);
                }
            }

            return [
                'slug' => 'favicon',
                'label' => $host,
                'favicon' => 'https://www.google.com/s2/favicons?domain='.urlencode($host).'&sz=64',
            ];
        }

        return self::data($manualIcon ?: 'link');
    }

    public static function detectSlug(string $url): string
    {
        $res = self::resolve($url);

        return $res['slug'];
    }

    public static function render(string $url, ?string $manualIcon = null, string $class = 'w-5 h-5'): string
    {
        $res = self::resolve($url, $manualIcon);

        if (! empty($res['favicon'])) {
            return '<img src="'.e($res['favicon']).'" alt="" class="'.$class.' flex-shrink-0" loading="lazy" referrerpolicy="no-referrer">';
        }

        return self::markup($res['slug'], $class);
    }

    private static function data(string $slug): array
    {
        return [
            'slug' => $slug,
            'label' => self::label($slug),
            'favicon' => null,
        ];
    }
}